from qgis.PyQt.QtWidgets import QAction, QDockWidget

mw = iface.mainWindow()
dock = mw.findChild(QDockWidget, 'AdvancedDigitizingTools')
out = {}
for a in dock.findChildren(QAction):
    if a.objectName() == 'mToolsAction':
        out['before'] = {
            'text': a.text(), 'tooltip': a.toolTip(),
            'enabled': a.isEnabled(), 'checkable': a.isCheckable(), 'checked': a.isChecked(),
            'has_menu': a.menu() is not None,
        }
        # メニュー内容
        if a.menu() is not None:
            out['menu_items'] = [sa.text() for sa in a.menu().actions()]
        if a.isEnabled():
            a.trigger()
            out['after'] = {'checked': a.isChecked()}
        else:
            a.setEnabled(True)
            a.trigger()
            out['after'] = {'checked': a.isChecked(), 'note': 'force-enabled'}
        break
result = out
