from qgis.PyQt.QtWidgets import QAction, QDockWidget, QToolButton, QMenu

mw = iface.mainWindow()
dock = mw.findChild(QDockWidget, 'AdvancedDigitizingTools')
out = {}
for a in dock.findChildren(QAction):
    if a.objectName() == 'mToolsAction':
        try:
            objs = a.associatedObjects()
        except Exception:
            objs = []
        out['associated'] = [type(w).__name__ + ':' + (w.objectName() or '') for w in objs]
        # 関連ボタンのメニューを取得
        for w in objs:
            if isinstance(w, QToolButton):
                m = w.menu()
                if m is not None:
                    out['btn_menu'] = [sa.text() for sa in m.actions()]
                out['popupMode'] = str(w.popupMode())
        out['checked'] = a.isChecked()
        break
result = out
"}
